package cn.mop.persistence;
import com.zaxxer.hikari.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import java.sql.*;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
/** Restricted real PostgreSQL schema checks. Most rows roll back; one committed synthetic draft is retained. */
@EnabledIfEnvironmentVariable(named="MOP_RUN_REMOTE_TESTS",matches="true")
class PostgresBackupPlanSchemaIntegrationTest {
    static HikariDataSource pool;
    static final String TENANT="55000000-0000-4000-8000-000000000001";
    Connection c;String actor,asset,otherAsset,foreignAsset;
    @BeforeAll static void connect(){String url=System.getenv("SPRING_DATASOURCE_URL");assertNotNull(url);assertTrue(url.matches("jdbc:postgresql://127\\.0\\.0\\.1:[0-9]+/mop_test"));assertEquals("mop_test_runtime",System.getenv("SPRING_DATASOURCE_USERNAME"));var cfg=new HikariConfig();cfg.setJdbcUrl(url);cfg.setUsername(System.getenv("SPRING_DATASOURCE_USERNAME"));cfg.setPassword(System.getenv("SPRING_DATASOURCE_PASSWORD"));cfg.setMaximumPoolSize(2);cfg.setConnectionTimeout(5000);pool=new HikariDataSource(cfg);}
    @BeforeEach void begin()throws Exception{c=pool.getConnection();c.setAutoCommit(false);actor=scalar("SELECT user_id::text FROM public.mop_membership WHERE tenant_id='"+TENANT+"' AND role_code='padmin' AND active ORDER BY user_id LIMIT 1");asset=scalar("SELECT id::text FROM public.mop_asset WHERE tenant_id='"+TENANT+"' ORDER BY id LIMIT 1");otherAsset=scalar("SELECT id::text FROM public.mop_asset WHERE tenant_id='"+TENANT+"' ORDER BY id OFFSET 1 LIMIT 1");foreignAsset=scalar("SELECT id::text FROM public.mop_asset WHERE tenant_id<>'"+TENANT+"' ORDER BY id LIMIT 1");}
    @AfterEach void rollback()throws Exception{if(c!=null){c.rollback();c.close();}}
    @AfterAll static void close(){if(pool!=null)pool.close();}
    void sql(String value)throws SQLException{try(var s=c.createStatement()){s.execute(value);}}
    String scalar(String value)throws SQLException{try(var s=c.createStatement();var r=s.executeQuery(value)){assertTrue(r.next());return r.getString(1);}}
    @FunctionalInterface interface Action{void run()throws Exception;}
    void rejected(String state,Action action)throws Exception{var p=c.setSavepoint();var e=assertThrows(SQLException.class,action::run);assertEquals(state,e.getSQLState());c.rollback(p);c.releaseSavepoint(p);}
    void validate()throws SQLException{sql("SET CONSTRAINTS ALL IMMEDIATE");sql("SET CONSTRAINTS ALL DEFERRED");}
    String head()throws SQLException{String id=UUID.randomUUID().toString();sql("INSERT INTO public.mop_backup_plan_draft(id,tenant_id,created_by) VALUES ('"+id+"','"+TENANT+"','"+actor+"')");return id;}
    void revision(String id,int v,String action,int count,String name,String time,String note)throws SQLException{
        try(var s=c.prepareStatement("INSERT INTO public.mop_backup_plan_revision(tenant_id,plan_id,version,previous_version,recorded_by,action,archived,name,daily_local_time,requested_enabled,target_count,note) VALUES (?::uuid,?::uuid,?,?,?::uuid,?,?,?,?,true,?,?)")){s.setString(1,TENANT);s.setString(2,id);s.setInt(3,v);if(v==1)s.setNull(4,Types.BIGINT);else s.setInt(4,v-1);s.setString(5,actor);s.setString(6,action);s.setBoolean(7,action.equals("ARCHIVE"));s.setString(8,name);s.setString(9,time);s.setInt(10,count);s.setString(11,note);s.executeUpdate();}
    }
    void target(String id,int v,int position,String target)throws SQLException{sql("INSERT INTO public.mop_backup_plan_target(tenant_id,plan_id,version,position,asset_id) VALUES ('"+TENANT+"','"+id+"',"+v+","+position+",'"+target+"')");}
    void complete(String id,int v,String action,String name,String time,List<String> refs)throws SQLException{revision(id,v,action,refs.size(),name,time,null);int n=0;for(String ref:refs)target(id,v,++n,ref);if(v>1)sql("UPDATE public.mop_backup_plan_draft SET version="+v+",updated_at=statement_timestamp() WHERE id='"+id+"'");validate();}
    String create()throws SQLException{String id=head();complete(id,1,"CREATE","SYNTHETIC_BACKUP_PLAN_SCHEMA","02:00",List.of(asset));return id;}
    @Test void actualStructureAclAndGuardBodiesMatch()throws Exception{BackupPlanSchemaVerifier.verify(c);assertEquals("mop_test_runtime",scalar("SELECT current_user"));}
    @Test void enabledIntentNeverEnablesOrApprovesStoredProposal()throws Exception{String id=create();assertEquals("true,false,false,DRAFT,UNVERIFIED,Asia/Shanghai",scalar("SELECT requested_enabled||','||enabled||','||effective||','||lifecycle_status||','||approval_status||','||timezone FROM public.mop_backup_plan_revision WHERE plan_id='"+id+"'"));}
    @Test void missingCurrentRevisionFailsDeferredValidation()throws Exception{rejected("23503",()->{head();validate();});}
    @Test void incompleteTargetsFailDeferredBoundary()throws Exception{rejected("23514",()->{String id=head();revision(id,1,"CREATE",2,"SYNTHETIC","02:00",null);target(id,1,1,asset);validate();});}
    @Test void orderedTargetsHaveSameTenantForeignKeys()throws Exception{String id=head();complete(id,1,"CREATE","SYNTHETIC","02:00",List.of(otherAsset,asset));assertEquals(otherAsset+","+asset,scalar("SELECT string_agg(asset_id::text,',' ORDER BY position) FROM public.mop_backup_plan_target WHERE plan_id='"+id+"'"));rejected("23503",()->{String bad=head();revision(bad,1,"CREATE",1,"SYNTHETIC","02:00",null);target(bad,1,1,foreignAsset);});}
    @Test void duplicateAndOutOfRangeTargetPositionsFail()throws Exception{String id=head();revision(id,1,"CREATE",2,"SYNTHETIC","02:00",null);target(id,1,1,asset);rejected("23505",()->target(id,1,2,asset));rejected("23514",()->target(id,1,3,otherAsset));}
    @Test void headCannotSkipOrRepeatLogicalVersion()throws Exception{String id=create();for(int v:List.of(0,1,3))rejected("23514",()->sql("UPDATE public.mop_backup_plan_draft SET version="+v+" WHERE id='"+id+"'"));}
    @Test void futureRevisionWithoutHeadAdvanceCannotCommit()throws Exception{String id=create();rejected("23514",()->{revision(id,2,"UPDATE",1,"SYNTHETIC","03:00",null);target(id,2,1,asset);validate();});}
    @Test void updatePreservesOriginalRevisionAndOrderedTargets()throws Exception{String id=create();String before=scalar("SELECT to_jsonb(r)::text FROM public.mop_backup_plan_revision r WHERE plan_id='"+id+"' AND version=1");complete(id,2,"UPDATE","改名","03:00",List.of(otherAsset,asset));assertEquals(before,scalar("SELECT to_jsonb(r)::text FROM public.mop_backup_plan_revision r WHERE plan_id='"+id+"' AND version=1"));assertEquals("2",scalar("SELECT version FROM public.mop_backup_plan_draft WHERE id='"+id+"'"));}
    @Test void archiveAndRestorePreserveProposalWithoutActivating()throws Exception{String id=create();complete(id,2,"ARCHIVE","SYNTHETIC_BACKUP_PLAN_SCHEMA","02:00",List.of(asset));complete(id,3,"RESTORE","SYNTHETIC_BACKUP_PLAN_SCHEMA","02:00",List.of(asset));assertEquals("CREATE,ARCHIVE,RESTORE",scalar("SELECT string_agg(action,',' ORDER BY version) FROM public.mop_backup_plan_revision WHERE plan_id='"+id+"'"));assertEquals("false",scalar("SELECT bool_or(enabled)::text FROM public.mop_backup_plan_revision WHERE plan_id='"+id+"'"));}
    @Test void archiveCannotAlterNameTimeOrTargets()throws Exception{String id=create();rejected("23514",()->complete(id,2,"ARCHIVE","changed","02:00",List.of(asset)));rejected("23514",()->complete(id,2,"ARCHIVE","SYNTHETIC_BACKUP_PLAN_SCHEMA","03:00",List.of(asset)));rejected("23514",()->complete(id,2,"ARCHIVE","SYNTHETIC_BACKUP_PLAN_SCHEMA","02:00",List.of(otherAsset)));}
    @Test void archivedUpdateAndUnneededRestoreAreRejected()throws Exception{String id=create();rejected("23514",()->complete(id,2,"RESTORE","SYNTHETIC_BACKUP_PLAN_SCHEMA","02:00",List.of(asset)));complete(id,2,"ARCHIVE","SYNTHETIC_BACKUP_PLAN_SCHEMA","02:00",List.of(asset));rejected("23514",()->complete(id,3,"UPDATE","changed","02:00",List.of(asset)));}
    @Test void strictClockAndUnicodeNameConstraintsMatchCore()throws Exception{for(String time:List.of("2:00","24:00","02:60"))rejected("23514",()->revision(head(),1,"CREATE",1,"SYNTHETIC",time,null));for(String name:List.of("","\u00a0","\ufeff","bad\nname"))rejected("23514",()->revision(head(),1,"CREATE",1,name,"02:00",null));String id=head();revision(id,1,"CREATE",1,"😀".repeat(100),"23:59","\n\t😀");target(id,1,1,asset);validate();}
    @Test void nullAndEmptyNotesRemainDistinct()throws Exception{String a=head(),b=head();revision(a,1,"CREATE",1,"SYNTHETIC","02:00",null);target(a,1,1,asset);revision(b,1,"CREATE",1,"SYNTHETIC","02:00","");target(b,1,1,asset);validate();assertEquals("true",scalar("SELECT (note IS NULL)::text FROM public.mop_backup_plan_revision WHERE plan_id='"+a+"'"));assertEquals("",scalar("SELECT note FROM public.mop_backup_plan_revision WHERE plan_id='"+b+"'"));}
    @Test void storedFlagsCannotBeOverriddenOnInsert()throws Exception{for(String field:List.of("enabled","effective"))rejected("23514",()->sql("INSERT INTO public.mop_backup_plan_revision(tenant_id,plan_id,version,recorded_by,action,name,daily_local_time,requested_enabled,target_count,"+field+") VALUES ('"+TENANT+"','"+head()+"',1,'"+actor+"','CREATE','SYNTHETIC','02:00',true,1,true)"));}
    @Test void forgedCreationTransactionIsRejected()throws Exception{String id=head();rejected("23514",()->sql("INSERT INTO public.mop_backup_plan_revision(tenant_id,plan_id,version,recorded_by,action,name,daily_local_time,requested_enabled,target_count,creation_xid) VALUES ('"+TENANT+"','"+id+"',1,'"+actor+"','CREATE','SYNTHETIC','02:00',true,1,'1'::xid8)"));}
    @Test void runtimeCannotRewriteDeleteTruncateOrRebind()throws Exception{String id=create();for(String table:List.of("mop_backup_plan_draft","mop_backup_plan_revision","mop_backup_plan_target")){rejected("42501",()->sql("DELETE FROM public."+table+" WHERE false"));rejected("42501",()->sql("TRUNCATE public."+table));}rejected("42501",()->sql("UPDATE public.mop_backup_plan_draft SET created_by='"+actor+"' WHERE id='"+id+"'"));rejected("42501",()->sql("UPDATE public.mop_backup_plan_revision SET name='changed' WHERE plan_id='"+id+"'"));rejected("42501",()->sql("UPDATE public.mop_backup_plan_target SET position=2 WHERE plan_id='"+id+"'"));}
    @Test void committedRevisionCannotReceiveLaterTargetsEvenAtExistingPosition()throws Exception{String id=create();c.commit();rejected("23514",()->target(id,1,1,otherAsset));assertEquals("1",scalar("SELECT count(*) FROM public.mop_backup_plan_target WHERE plan_id='"+id+"'"));}
    @Test void earlyConstraintValidationDoesNotAllowExtraTarget()throws Exception{String id=create();sql("SET CONSTRAINTS ALL IMMEDIATE");rejected("23514",()->target(id,1,2,otherAsset));assertEquals("1",scalar("SELECT count(*) FROM public.mop_backup_plan_target WHERE plan_id='"+id+"'"));}
}
